INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1, 190801, "カリン", 3.414, 2, "2025/01/31 12:00:00", "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 1, 1000001, 1, 0, "2030/01/01 14:59:59", 62, -416.5);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (2, 190801, "カリン", 3.099, 2, "2025/01/31 12:00:00", "ミッションをクリアして、\n報酬をゲットしましょう！", 1, 1000002, 1, 0, "2030/01/01 14:59:59", 62, -416.5);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (3, 190801, "カリン", 2.801, 2, "2025/01/31 12:00:00", "受け取ることができる\n報酬があるようです\n確認してみてください", 1, 1000003, 1, 0, "2030/01/01 14:59:59", 63, -416.5);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (4, 190801, "カリン", 0, 2, "2025/01/31 12:00:00", "報酬がもらえますよ！\nチェックしてみてください", 2, 1000004, 1, 0, "2030/01/01 14:59:59", 63, -416.5);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (5, 190801, "カリン", 2.12, 1, "2025/01/31 12:00:00", "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", 2, 1000005, 1, 0, "2030/01/01 14:59:59", 64, -363);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (6, 190801, "カリン", 1.68, 2, "2025/01/31 12:00:00", "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", 1, 1000006, 1, 0, "2030/01/01 14:59:59", 64, -363);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (7, 190801, "カリン", 2.33, 1, "2025/01/31 12:00:00", "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", 2, 1000007, 1, 0, "2030/01/01 14:59:59", 64, -363);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (101, 133701, "ラビリスタ", 5.18, 7, "2025/01/31 12:00:00", "今度の敵は、アタシにとっても\n放ってはおけない存在だ\n少年、アタシも全力で行くからさ\n一緒に守ろう、この世界を", 3, 1020101, 10201, -6, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (201, 133901, "クリスティーナ", 8.77, 2, "2025/01/31 12:00:00", "退屈の吹き飛ぶような\n戦いの気配がするなぁ坊や\nさっさとワタシをそこへ連れてゆけ\n世界も守ってやるさ、ついでにな", 1, 1020102, 10201, -2, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (301, 133801, "ネネカ", 15.5, 1, "2025/01/31 12:00:00", "おや、私の力が必要……と？\nグレゴールが手伝うそうですよ\n私は戦わないのか、という顔ですね\n……考えておきます", 6, 1020103, 10201, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (101, 134301, "ランファ", 9.061, 5, "2025/02/28 12:00:00", "わたしだけの歌…\n一緒に、探してくれる…？\nあなたがいれば…\nもっとがんばれるから…", 2, 1020201, 10202, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (201, 134401, "チカ", 7.699, 2, "2025/02/28 12:00:00", "同じ唱喚士として、仲間として\n私にできることをします\n…これも、あなたが\n背中を押してくれたおかげですよ", 1, 1020202, 10202, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (101, 134601, "アオイ", 8.595, 2, "2025/03/31 12:00:00", "世界の平和が私とクローチェさんに\nかかってるんですよね？\nぼっちには過大すぎる期待ですけど\nふ、二人でなら背負ってみせます！", 1, 1020301, 10203, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (201, 134501, "クローチェ", 7.758, 2, "2025/03/31 12:00:00", "新しく手に入れたこの翼で…\nナイトさんがどこにいたって\nわたし、駆けつけちゃいますよっ！\nクローチェ・エアリアル発進ですっ", 1, 1020302, 10203, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (101, 132302, "ルイズマリー", 7, 6, "2025/04/30 12:00:00", "今日はダーリンとの初デート♪\n二人でショッピングして、その後は\n…って私、指名手配されてる！？\nちょ、た…助けてダーリン～！！", 2, 1020401, 10204, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (201, 132402, "イロハ", 7.904, 2, "2025/04/30 12:00:00", "ルイちゃんのおばあちゃん優しくて\nいつもにこにこで、イロハ大好き♪\nでも一番好きなのは、角がすっごく\n大きくてかっこいいとこなんだ～♪", 1, 1020402, 10204, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (301, 132502, "ソノ", 8.487, 2, "2025/04/30 12:00:00", "ノゾミちゃんのおかげで売上が安定\nしてきたのに、臨時休業、痛すぎる\n…ま、ルイちゃんのために\n一肌脱ぐか。行くよイロハ～", 4, 1020403, 10204, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (101, 134901, "カノン", 8.763, 2, "2025/05/31 12:00:00", "ヲ～ッホッホ♪\nあたくし様と同じお空気を吸える\nお幸運を噛みしめなさいですわ～♪\nヲ～ッホッホッホ～♪", 1, 1020502, 10205, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (201, 134801, "ツムギ", 6.417, 3, "2025/05/31 12:00:00", "いきますよ騎士さん！\nカノンさんと力を合わせて…力を…\n…本当にあの人なんなんです？\nこれまでになく不安なんですけど！", 1, 1020503, 10205, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (101, 135001, "エリス", 10.335, 7, "2025/06/30 12:00:00", "『願いが叶う海岸』か…怪しい\nだというのに、阿賀斗紫布菜たちは\n呑気に戯れている…見ていられない\n騎士クンは、わたしが守ってみせる", 3, 1020601, 10206, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (201, 135101, "シェフィ", 6.281, 4, "2025/06/30 12:00:00", "せっかくの夏休みなんだし\nたまにはビーチでゆっくりしましょ\n…え、もしかしてこの夏もあんまり\n休めなかったりする感じなの？", 2, 1020602, 10206, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (301, 135201, "プレシア", 12.244, 2, "2025/06/30 12:00:00", "いっぱい。たべて\nおおきく。なると\nせーぎ。まもれる。はず\nお兄。いっしょに。スイカ。たべよ", 1, 1020603, 10206, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (101, 135301, "クリア", 6.339, 8, "2025/07/31 12:00:00", "ひと夏の冒険のはじまりです！\nアネモネさんも楽しんでくれたら\n…できれば、もう少し\n仲良くなれたらうれしいな…", 2, 1020701, 10207, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (201, 135401, "アネモネ", 8.184, 9, "2025/07/31 12:00:00", "─幻の花…\n本当にあるのか謎─ですけど\n探すくらいは、\n付き合ってもいいです", 7, 1020702, 10207, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (101, 129101, "アイラ", 3.906, 2, "2025/08/31 12:00:00", "あははっ！　笑う門には福来る！\n笑ってればきっと、複製世界にも\n未来はやってくるって信じてる！\nそうだよね、シナツちゃん！", 9, 1020801, 10208, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (201, 129201, "シナツ", 14.465, 2, "2025/08/31 12:00:00", "繰り返されるリセットの先の未来\n何度願っても手に入らなかった未来\n…でも、私は諦めない。絶対にだ\nキミも同じだろ…アイラ？", 1, 1020802, 10208, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (301, 100101, "ヒヨリ", 8.662, 3, "2025/08/31 12:00:00", "アイラの世界のみんなも、\n一生懸命生きてるんだ…！\n…なのに、世界の危機だなんて！\nあたし、絶対、絶対力になるよ！", 4, 1020803, 10208, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (401, 100301, "レイ", 10.915, 3, "2025/08/31 12:00:00", "シナツ…もう一人の私\n彼女が大切にしている世界を\n絶対に終わらせはしない…！\n彼女と笑い合える未来のために！", 1, 1020804, 10208, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (101, 135802, "ユキノ", 6.042, 7, "2025/09/30 12:00:00", "あ、ど、ども…\nあ、あんま見ねぇでくれっと\nその、恥ずかしくて…\n体が熱くなって、溶けちまう…", 1, 1020901, 10209, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (201, 135903, "サツキ", 9.402, 1, "2025/09/30 12:00:00", "なんで俺が幽霊に…意味不明だ\nこれじゃ死んでも死にきれねェ\n悪ィがこれも何かの縁だ、\nよろしく頼むぜ騎士公", 4, 1020902, 10209, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (301, 136902, "ルルィ", 8.16, 1, "2025/09/30 12:00:00", "う、うじゅる…\nサツキ姉しゃまを助けるためにも\nまずは、腹ごしらえでしゅね…！\nタコ焼き、召し上がってくだしゃい", 8, 1020903, 10209, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (101, 137401, "カスミ", 5, 2, "2025/10/31 12:00:00", "ひさしぶりのジオ・ゲヘナ\n歓迎パーティーで起きた殺人事件！\nランドソルの名探偵の名にかけて\n解き明かしてみせようじゃないか！", 3, 1021001, 10210, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (201, 136001, "アラクネ", 8.12, 1, "2025/10/31 12:00:00", "…わたしはどこの誰なのでしょう\nどこから来てどこへ行くのでしょう\nこの事件の真相が分かれば、\n何かが掴めるような気がいたします", 4, 1021002, 10210, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (301, 136202, "ナーナ", 6.386, 2, "2025/10/31 12:00:00", "ナーナ、すいりとかろんぱとか、\nむずかしくてわかんないけど…\nお友だちとドーナツのためならっ\nせーいっぱいがんばるよっ！", 4, 1021003, 10210, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (101, 136402, "ユイ", 7.438, 4, "2025/11/30 12:00:00", "騎士クンに想いを伝えたい…だから\nミソラちゃん、わたしがんばるね！\n…あれ？　わたし、なんでこんなに\n必死になってるんだろう…？", 3, 1021101, 10211, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (201, 136302, "ミソラ", 8.35, 5, "2025/11/30 12:00:00", "騎士さんとのデートはわたしに\nお任せです★　なのでユイさんは\n安心して計画に専念して…たくさん\nドキドキしちゃってくださいね", 1, 1021102, 10211, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (101, 136501, "シズル", 5, 2, "2025/12/31 12:00:00", "新しい年がやってくるね！\nお正月の料理も飾りつけも、\nお姉ちゃんにお任せだよ♪\nみんなで楽しく新年を迎えよう！", 1, 1021201, 10212, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (201, 137902, "リノ", 5.25, 2, "2025/12/31 12:00:00", "おうちの掃除もトラブルも、 \n世界を揺るがす大ピンチも！\n今年のことは今年のうちに \nサッサと片付けちゃいますっ！", 1, 1021202, 10212, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (301, 106801, "ラビリスタ", 7.5, 2, "2025/12/31 12:00:00", "年の瀬はギルドマスターも\nつい駆け回っちゃう忙しい時期だ！\n一年いろいろあったけど\nお互いイイ年を迎えよう、少年！", 1, 1021203, 10212, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (101, 126501, "ライラエル", 8.204, 2, "2026/01/31 12:00:00", "漂う異国の料理の香り…それだけで\n世界中を旅した気分に浸れますね\nふふ、ほらクローチェ\nあまりはしゃぎすぎないように…♪", 1, 1021301, 10213, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (201, 129701, "ネフィ＝ネラ", 7.176, 2, "2026/01/31 12:00:00", "異界の姫君と煮炊きにて競い合う…\n感奮興起、いとをかし\n華やかなる祭典と相成るよう、一肌\n脱がせていただきとう存じまする", 1, 1021302, 10213, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (301, 133101, "ヴァイオレット", 8.602, 5, "2026/01/31 12:00:00", "『ビストロプリンセス』のために\n料理の特訓を重ねてまいりました\nこの料理で騎士様の…い、いえ\n皆様の心とお腹を満たしますわ！", 1, 1021303, 10213, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (102, 138101, "ライラエル", 10.14, 3, "2026/02/06 12:00:00", "多様な味わいが織りなすハーモニー\nそれこそが我が国の矜持です\nもしもそれを乱すようであれば\nわたしも優しくはありませんよ？", 1, 1021304, 10213, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (202, 138201, "ネフィ＝ネラ", 10.152, 7, "2026/02/06 12:00:00", "煉獄の穢土にてひと際輝く民草の心\n此れを守護りまするがわっちの責務\n如何な困難待ち受けようと\n不退転の矜持に揺らぎはありんせん", 1, 1021305, 10213, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (302, 138001, "ヴァイオレット", 9.688, 3, "2026/02/06 12:00:00", "裏世界の皆様は危機を脱し、\n残るはランドソルの皆様のみ…\n彼らを救い出すために、どうか…\nお立ち下さいペコリーヌ姫…！", 4, 1021306, 10213, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (401, 138301, "ペコリーヌ", 5.928, 1, "2026/02/12 12:00:00", "みなさん、お待たせしちゃいました\nペコリーヌ、完全復活です☆\nみなさんの食卓を守るため\nもう二度と、わたしはめげません！", 2, 1021307, 10213, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (101, 138702, "ワカナ", 9.19, 2, "2026/02/28 12:00:00", "成行きで参加することになっちゃっ\nた尻相撲大会。ううっ、恥ずかしい\nけどやるしかないよね。…騎士さん\nいっぱい応援してくださいね？", 4, 1021401, 10214, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (201, 138802, "シオリ", 8.724, 3, "2026/02/28 12:00:00", "「お姉ちゃんを守れる自分になる」\nあの日の約束、今こそ果たしてみせ\nます。例えお姉ちゃんに背くことに\nなっても。例えそれが尻相撲でも！", 1, 1021402, 10214, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (101, 138902, "グレイス", 7.758, 1, "2026/03/31 12:00:00", "私がへんたいふしんしゃさんって…\nただ生きているだけなのに、ひどい\n…まぁ死んでるんですけど…とか\n言ってる暇もない感じですか？", 4, 1021501, 10215, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (201, 139002, "キョウカ", 6.375, 4, "2026/03/31 12:00:00", "あの、助けてください！\n私がへんたいふしんしゃさんに\nなっちゃったみたいなんです…！\nどういう意味かは私もわかりません", 6, 1021502, 10215, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (301, 136902, "ルルィ", 6.173, 1, "2026/03/31 12:00:00", "ましゃか、グレイス姉しゃまたちが\nへんたいふしんしゃさんだなんて…\n騎士しゃん。あたちたちも協力ちて\n二人の破滅エンドを回避ちましょう", 6, 1021503, 10215, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (101, 139202, "ミホ", 4.202, 2, "2026/04/30 12:00:00", "違う世界に来ちゃうし、\n驚きの連続だけど…\nわたしも精いっぱい頑張ります！\nアストルムのみんなと一緒に！", 6, 1021601, 10216, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (201, 139302, "マホ", 2.842, 1, "2026/04/30 12:00:00", "想定外の事象が発生したな…だが\nいかなる苦境も切り抜けてみせる\nいつもの自分とは違う姿になっても\nわたしはわたし、西住流だ", 6, 1021602, 10216, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (301, 139402, "エリカ", 4.598, 1, "2026/04/30 12:00:00", "何でこんなことになっているのか\n全然わからないけど、迷ってる暇は\nないわ。黒森峰の次期隊長として、\n前進あるのみ！　これも戦車道よ！", 4, 1021603, 10216, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (101, 125802, "リリ", 6.533, 3, "2026/05/31 12:00:00", "わたくしたちの悲願は、ロストさせ\nてしまった方々をお助けすること…\nそのためなら、どのような辛苦にも\n耐え抜いてみせます…！", 4, 1021701, 10217, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (301, 126102, "プレシア", 5, 3, "2026/05/31 12:00:00", "みんなも。せーぎも。\nクリアも。パパ、も。\nぜったい、たすける。\nみててね。お兄。", 3, 1021702, 10217, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (201, 126002, "クリア", 5.214, 4, "2026/05/31 12:00:00", "癒しの力を使うこと…\nもう、ためらいません！\nモネちゃんやお兄さん…\nみんなに許してもらうためにも！", 3, 1021703, 10217, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (102, 139501, "リリ", 8.781, 3, "2026/05/31 12:00:00", "ヴァルキュリア─皆様を助けたい\nという願いを、力にできるのなら…\nわたくしたちは、きっと誰にも\n負けません！　一意専心です…！", 1, 1021704, 10217, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (202, 139601, "クリア", 6.529, 1, "2026/05/31 12:00:00", "このヴァルキュリアって職業、\nまるで天使みたいな格好ですよね\nうーん…『聖女』ちゃんって\n呼ばれるよりは、マシかな？", 2, 1021705, 10217, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (302, 139701, "プレシア", 3.195, 2, "2026/05/31 12:00:00", "ばるきり。もーど。\nはね。まっしろ。\nはっぴーちゃんと。おなじ。\nいいかんじ。", 3, 1021706, 10217, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (101, 139902, "ルイズマリー", 12.43, 3, "2026/06/30 12:00:00", "ダーリンと一緒に南の島で\nリゾート開発なんて夢みたい♪\nああ…幸せ、最高の夏だわ…\n触れたら爆発さえしなければ～…っ", 2, 1021801, 10218, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (201, 140001, "クレジッタ", 6.35, 3, "2026/06/30 12:00:00", "青い空、白い雲…無人島リゾートで\n大儲けですわ～♪　こらこらそこ、\nイチャついてるんじゃないですのよ\n触れたらドカンですわよ、ドカン！", 2, 1021802, 10218, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (101, 140102, "フブキ", 10.23, 5, "2026/07/31 12:00:00", "みんなはかわいいぼくを見られて、\nぼくはみんなからラヴをもらう♡\n最高のウィンウィンだよね、これ♡\nで、最後はお兄さんをドレーに…♡", 1, 1021901, 10219, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (201, 140201, "ヴァンピィ", 5.584, 2, "2026/07/31 12:00:00", "けんぞくとたくさん遊ぶためにも、\nみんなからラヴをもらわなくちゃ♪\nバズっちゃおー作戦、\n一緒に考えてね！　けんぞくぅ♪", 1, 1021902, 10219, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (201, 126401, "クローチェ", 2.8, 3, "2026/08/31 12:00:00", "あっちもこっちも、\nエマージェンシーですっ！\nみんなのピンチを助けるために\n行きましょうっ、ナイトさんっ！", 6, 1022001, 10220, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (101, 127802, "ヴルム", 8.9, 3, "2026/08/31 12:00:00", "みんながあたしを許してくれても…\nあたしは、あたしを許せない\nそれでも…この世界が危ないなら\n迷ってなんか、いられない", 4, 1022002, 10220, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (202, 140602, "クローチェ", 4.49, 1, "2026/08/31 12:00:00", "クローチェ、サブマリンモードっ\n換装完了ですっ♪\nどんな荒波も、ナイトさんとなら\n越えちゃいますからっ！", 2, 1022003, 10220, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (102, 140501, "ヴルム", 9.42, 3, "2026/08/31 12:00:00", "偽物でも、創り物でもいい\nあたしの中にある気持ちは、\nあたしの本物だから\n今度こそ、この力で守ってみせる", 1, 1022004, 10220, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (301, 140402, "リーザ", 7, 1, "2026/08/31 12:00:00", "世界と向き合うなんてこと…\n私には、わからない\nそれでも、受けた借りは\nちゃんと返さないとね", 4, 1022005, 10220, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (101, 141101, "アーモンドアイ", 8.61, 3, "2026/10/31 12:00:00", "ゲームの世界、ね\n分からないことばかりだけれど\nやることは変わらないわ\nどんな場所でもわたしは負けない！", 1, 1022101, 10221, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (201, 141201, "ラッキーライラック", 3.55, 1, "2026/10/31 12:00:00", "ゴルシさんは相変わらずやねぇ…\nまぁせっかくの異世界やし\nいつもと違うレース、\n楽しませてもらいましょ", 6, 1022102, 10221, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (301, 141301, "デアリングタクト", 8.26, 1, "2026/10/31 12:00:00", "なんて美しい世界でしょう…！\n現実では見られない景色ばかり\nぜひ一度、この世界の大自然を\n隅から隅まで駆け抜けてみたいです", 2, 1022103, 10221, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (401, 141001, "ゴールドシップ", 8.79, 1, "2026/10/31 12:00:00", "来ったぞ～来ったぞ～\nアストルム～っと！\nな～んか平和そうな世界だな\nちょっくら盛り上げてくっか！", 2, 1022104, 10221, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (101, 141101, "アーモンドアイ", 8.61, 3, "2026/10/31 12:00:00", "ゲームの世界、ね\n分からないことばかりだけれど\nやることは変わらないわ\nどんな場所でもわたしは負けない！", 1, 1022105, 10221, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (202, 141201, "ラッキーライラック", 2.69, 2, "2026/10/31 12:00:00", "（剣と魔法！　ええなぁ～！\nうちも魔法覚えられるやろか\nレースの後に花咲かせたり…\nくぅ～っ！　はよ試したいわ！）", 1, 1022106, 10221, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (301, 141301, "デアリングタクト", 8.26, 1, "2026/10/31 12:00:00", "なんて美しい世界でしょう…！\n現実では見られない景色ばかり\nぜひ一度、この世界の大自然を\n隅から隅まで駆け抜けてみたいです", 2, 1022107, 10221, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (401, 141001, "ゴールドシップ", 8.79, 1, "2026/10/31 12:00:00", "来ったぞ～来ったぞ～\nアストルム～っと！\nな～んか平和そうな世界だな\nちょっくら盛り上げてくっか！", 2, 1022108, 10221, 0, "2030/01/01 14:59:59", 61, -285);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1, 190805, "カリン", 3.414, 2, "2026/04/10 12:00:00", "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 1, 2000001, 2, 0, "2030/01/01 14:59:59", 62, -416.5);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (2, 190805, "カリン", 3.099, 2, "2026/04/10 12:00:00", "ミッションをクリアして、\n報酬をゲットしましょう！", 1, 2000002, 2, 0, "2030/01/01 14:59:59", 62, -416.5);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (3, 190805, "カリン", 2.801, 2, "2026/04/10 12:00:00", "受け取ることができる\n報酬があるようです\n確認してみてください", 1, 2000003, 2, 0, "2030/01/01 14:59:59", 63, -416.5);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (4, 190805, "カリン", 0, 2, "2026/04/10 12:00:00", "報酬がもらえますよ！\nチェックしてみてください", 2, 2000004, 2, 0, "2030/01/01 14:59:59", 63, -416.5);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (5, 190805, "カリン", 2.12, 1, "2026/04/10 12:00:00", "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", 2, 2000005, 2, 0, "2030/01/01 14:59:59", 64, -363);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (6, 190805, "カリン", 1.68, 2, "2026/04/10 12:00:00", "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", 1, 2000006, 2, 0, "2030/01/01 14:59:59", 64, -363);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (7, 190805, "カリン", 2.33, 1, "2026/04/10 12:00:00", "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", 2, 2000007, 2, 0, "2030/01/01 14:59:59", 64, -363);
